mapper.select:
SELECT DISTINCT c.industry_code industryCode, c.industry_name industryName FROM sys_industry_conf c LEFT JOIN sys_industry_ver_conf vc ON vc.industry_code = c.industry_code and vc.accept_node = c.accept_node WHERE c.STATUS = 1 AND c.delete_flag = 0 AND vc.STATUS = 1 AND vc.delete_flag = 0 and c.accept_node = #{acceptNode}
AND (c.industry_code like concat('%',#{keyword},'%') or c.industry_name like concat('%',#{keyword},'%'))
ORDER BY c.industry_code

SELECT DISTINCT vc.app_ver_code appVerCode, vc.app_ver_name appVerName FROM sys_industry_ver_conf vc WHERE vc.STATUS = 1 AND vc.delete_flag = 0 and vc.accept_node = #{acceptNode}
AND vc.industry_code = #{industryCode}
AND (vc.app_ver_code like concat('%',#{keyword},'%') or vc.app_ver_name like concat('%',#{keyword},'%'))
ORDER BY vc.app_ver_code

SELECT t1.associate_id, t1.dept_id FROM sys_associate_demo_account_dept_rel_t t1 WHERE t1.delete_flag = 0
AND t1.associate_id = #{associateId}
AND t1.dept_id = #{deptId}

SELECT t1.associate_id, t1.user_id FROM sys_associate_demo_account_user_rel_t t1 WHERE t1.delete_flag = 0
AND t1.associate_id = #{associateId}
AND t1.user_id = #{userId}
